const o=[{id:"blood-diseases-001",topicId:"blood-diseases",question:"Что такое лейкоз?",options:["Злокачественное заболевание кроветворной системы с неконтролируемым ростом аномальных лейкоцитов","Снижение уровня гемоглобина и эритроцитов","Наследственный дефект синтеза гемоглобина","Нарушение свёртываемости крови"],correctIndex:0,explanation:"Лейкоз — это злокачественное заболевание кроветворной системы, характеризующееся неконтролируемым ростом аномальных белых кровяных клеток (лейкоцитов) в костном мозге.",difficulty:"medium",tags:["лейкоз","определение"]},{id:"blood-diseases-002",topicId:"blood-diseases",question:"Какие из перечисленных терминов являются синонимами лейкоза?",options:["Рак крови, лейкемия","Малокровие, анемия","Гемартроз, гемофилия","Гипоксия, ишемия"],correctIndex:0,explanation:"Лейкоз также называют раком крови или лейкемией.",difficulty:"easy",tags:["лейкоз","синонимы"]},{id:"blood-diseases-003",topicId:"blood-diseases",question:"Где происходит неконтролируемый рост аномальных лейкоцитов при лейкозе?",options:["В костном мозге","В селезёнке","В лимфатических узлах","В печени"],correctIndex:0,explanation:"При лейкозе аномальные лейкоциты неконтролируемо растут в костном мозге, вытесняя нормальные клетки крови.",difficulty:"medium",tags:["лейкоз","костный мозг"]},{id:"blood-diseases-004",topicId:"blood-diseases",question:"Что происходит с нормальными клетками крови при лейкозе?",options:["Они вытесняются аномальными клетками, и их функции нарушаются","Они увеличиваются в размерах","Они начинают переносить больше кислорода","Их количество не меняется"],correctIndex:0,explanation:"Аномальные лейкоциты вытесняют нормальные клетки крови, нарушая их функции.",difficulty:"medium",tags:["лейкоз","патогенез"]},{id:"blood-diseases-005",topicId:"blood-diseases",question:"Что характеризует анемию (малокровие)?",options:["Снижение уровня гемоглобина и эритроцитов, ведущее к гипоксии тканей","Неконтролируемый рост лейкоцитов","Образование тромбов в сосудах","Повышение уровня тромбоцитов"],correctIndex:0,explanation:"Анемия — состояние, характеризующееся снижением уровня гемоглобина и эритроцитов, что ведёт к кислородному голоданию тканей (гипоксии).",difficulty:"medium",tags:["анемия","определение"]},{id:"blood-diseases-006",topicId:"blood-diseases",question:"К чему ведёт анемия на уровне тканей?",options:["К кислородному голоданию (гипоксии)","К образованию тромбов","К повышению свёртываемости крови","К росту опухолевых клеток"],correctIndex:0,explanation:"Анемия ведёт к кислородному голоданию тканей — гипоксии.",difficulty:"medium",tags:["анемия","гипоксия"]},{id:"blood-diseases-007",topicId:"blood-diseases",question:"Какой вид анемии наиболее распространён?",options:["Железодефицитная","Витаминодефицитная","Наследственная гемолитическая","Постгеморрагическая"],correctIndex:0,explanation:"Наиболее распространена железодефицитная анемия (из-за нехватки железа); также встречается витаминодефицитная (нехватка B12 или фолиевой кислоты).",difficulty:"medium",tags:["анемия","железодефицитная"]},{id:"blood-diseases-008",topicId:"blood-diseases",question:"Нехватка каких веществ вызывает витаминодефицитную анемию?",options:["Витамина B12 или фолиевой кислоты","Витамина C или витамина D","Железа или магния","Витамина A или витамина E"],correctIndex:0,explanation:"Витаминодефицитная анемия возникает при нехватке витамина B12 или фолиевой кислоты.",difficulty:"medium",tags:["анемия","витаминодефицитная","B12"]},{id:"blood-diseases-009",topicId:"blood-diseases",question:"Какие симптомы характерны для анемии?",options:["Бледность кожи, одышка при нагрузке, головокружение, постоянная усталость","Высокая температура и сыпь по всему телу","Резкое повышение артериального давления","Спонтанные кровоизлияния в суставы"],correctIndex:0,explanation:"Симптомы анемии: бледность кожи, одышка при нагрузке, головокружение, постоянная усталость.",difficulty:"medium",tags:["анемия","симптомы"]},{id:"blood-diseases-010",topicId:"blood-diseases",question:"Какие проявления со стороны сердца возможны при анемии (по схеме симптомов)?",options:["Учащённое сердцебиение, боли в груди, стенокардия","Замедление сердечного ритма до 30 в минуту","Полная остановка сердца без симптомов","Повышение давления до 200 мм рт. ст."],correctIndex:0,explanation:"По схеме симптомов анемии со стороны сердца возможны учащённое сердцебиение, боли в груди, стенокардия и даже сердечный приступ (при тяжёлой форме).",difficulty:"hard",tags:["анемия","симптомы","сердце"]},{id:"blood-diseases-011",topicId:"blood-diseases",question:"Какое изменение селезёнки отмечается на схеме симптомов анемии?",options:["Увеличение","Уменьшение","Полное отсутствие","Окостенение"],correctIndex:0,explanation:"На схеме симптомов анемии отмечается увеличение селезёнки.",difficulty:"hard",tags:["анемия","симптомы","селезёнка"]},{id:"blood-diseases-012",topicId:"blood-diseases",question:"Что такое талассемия?",options:["Наследственное заболевание, вызванное генетическим дефектом синтеза гемоглобина","Злокачественное заболевание кроветворной системы","Приобретённое нарушение свёртываемости крови","Воспаление костного мозга"],correctIndex:0,explanation:"Талассемия — наследственное заболевание, вызванное генетическим дефектом синтеза гемоглобина.",difficulty:"medium",tags:["талассемия","определение","наследственное"]},{id:"blood-diseases-013",topicId:"blood-diseases",question:"Что происходит с эритроцитами при талассемии?",options:["Они разрушаются быстрее нормы, вызывая хроническую анемию","Они перестают вырабатываться полностью","Они увеличиваются в размере и переносят больше кислорода","Они превращаются в лейкоциты"],correctIndex:0,explanation:"При талассемии эритроциты разрушаются быстрее нормы, что вызывает хроническую анемию.",difficulty:"medium",tags:["талассемия","эритроциты","гемолиз"]},{id:"blood-diseases-014",topicId:"blood-diseases",question:"Какие симптомы характерны для тяжёлых форм талассемии?",options:["Деформация костей, задержка роста, желтушность кожи","Высокое артериальное давление и ожирение","Образование тромбов в венах ног","Резкое повышение уровня лейкоцитов"],correctIndex:0,explanation:"Симптомы талассемии: деформация костей (при тяжёлых формах), задержка роста, желтушность кожи.",difficulty:"medium",tags:["талассемия","симптомы"]},{id:"blood-diseases-015",topicId:"blood-diseases",question:"Как характеризуется малая форма (Minor) талассемии?",options:["Бессимптомное носительство или лёгкая анемия","Тяжёлая форма с регулярными переливаниями","Полное отсутствие гемоглобина","Острое кровотечение из суставов"],correctIndex:0,explanation:"Малая форма (Minor) талассемии — это бессимптомное носительство или лёгкая анемия.",difficulty:"hard",tags:["талассемия","формы","Minor"]},{id:"blood-diseases-016",topicId:"blood-diseases",question:"Какая форма талассемии требует регулярных трансфузий крови с раннего возраста?",options:["Большая (Major)","Малая (Minor)","Промежуточная (Intermedia)","Скрытая"],correctIndex:0,explanation:"Большая форма (Major) — тяжёлая, требующая регулярных трансфузий крови с раннего возраста.",difficulty:"hard",tags:["талассемия","формы","Major"]},{id:"blood-diseases-017",topicId:"blood-diseases",question:"Как характеризуется промежуточная форма (Intermedia) талассемии?",options:["Симптомы средней тяжести, часто не требующие постоянных переливаний","Полностью бессимптомное течение","Тяжёлая форма с переливаниями с рождения","Острое жизнеугрожающее кровотечение"],correctIndex:0,explanation:"Промежуточная форма (Intermedia) — симптомы средней тяжести, часто не требующие постоянных переливаний крови.",difficulty:"hard",tags:["талассемия","формы","Intermedia"]},{id:"blood-diseases-018",topicId:"blood-diseases",question:"Что такое гемофилия?",options:["Генетическое нарушение свёртываемости крови из-за дефицита специфических факторов свёртывания","Злокачественное заболевание костного мозга","Снижение гемоглобина из-за нехватки железа","Воспаление стенок сосудов"],correctIndex:0,explanation:"Гемофилия — генетическое нарушение свёртываемости крови, связанное с дефицитом специфических факторов свёртывания (VIII или IX).",difficulty:"medium",tags:["гемофилия","определение"]},{id:"blood-diseases-019",topicId:"blood-diseases",question:"Какие симптомы характерны для гемофилии?",options:["Спонтанные кровоизлияния в суставы (гемартрозы), длительные кровотечения после мелких травм, обширные синяки","Бледность кожи и одышка при нагрузке","Деформация костей и задержка роста","Неконтролируемый рост лейкоцитов"],correctIndex:0,explanation:"Симптомы гемофилии: спонтанные кровоизлияния в суставы (гемартрозы), длительные кровотечения после мелких травм, обширные синяки.",difficulty:"medium",tags:["гемофилия","симптомы","гемартроз"]},{id:"blood-diseases-020",topicId:"blood-diseases",question:"Дефицит какого фактора свёртывания вызывает гемофилию А (классическую)?",options:["Фактора VIII (8)","Фактора IX (9)","Фактора XI (11)","Фактора X (10)"],correctIndex:0,explanation:"Гемофилия А (классическая) вызвана дефицитом фактора VIII (8).",difficulty:"hard",tags:["гемофилия","гемофилия А","фактор VIII"]},{id:"blood-diseases-021",topicId:"blood-diseases",question:"Какой тип гемофилии является самым распространённым (около 80–85% случаев)?",options:["Гемофилия А","Гемофилия B","Гемофилия C","Все типы встречаются одинаково часто"],correctIndex:0,explanation:"Гемофилия А (классическая) — самый распространённый тип, около 80–85% всех случаев.",difficulty:"medium",tags:["гемофилия","гемофилия А","частота"]},{id:"blood-diseases-022",topicId:"blood-diseases",question:"Кто преимущественно болеет гемофилией А, а кто является носителем гена?",options:["Болеют преимущественно мужчины, женщины — носители гена","Болеют преимущественно женщины, мужчины — носители","Болеют только дети до 5 лет","Болеют мужчины и женщины одинаково"],correctIndex:0,explanation:"Гемофилия А передаётся по наследству, болеют преимущественно мужчины, в то время как женщины являются носителями гена.",difficulty:"medium",tags:["гемофилия","гемофилия А","наследование"]},{id:"blood-diseases-023",topicId:"blood-diseases",question:"Как ещё называют гемофилию B?",options:["Болезнь Кристмаса","Болезнь Вильсона","Болезнь Аддисона","Классическая гемофилия"],correctIndex:0,explanation:"Гемофилия B также называется болезнью Кристмаса.",difficulty:"hard",tags:["гемофилия","гемофилия B","болезнь Кристмаса"]},{id:"blood-diseases-024",topicId:"blood-diseases",question:"Дефицит какого фактора свёртывания лежит в основе гемофилии B?",options:["Фактора IX (9)","Фактора VIII (8)","Фактора XI (11)","Фактора VII (7)"],correctIndex:0,explanation:"Гемофилия B (болезнь Кристмаса) обусловлена дефицитом фактора IX (9).",difficulty:"hard",tags:["гемофилия","гемофилия B","фактор IX"]},{id:"blood-diseases-025",topicId:"blood-diseases",question:"Дефицит какого фактора свёртывания характерен для гемофилии C?",options:["Фактора XI (11)","Фактора VIII (8)","Фактора IX (9)","Фактора XII (12)"],correctIndex:0,explanation:"Гемофилия C — очень редкая форма, вызванная дефицитом фактора XI.",difficulty:"hard",tags:["гемофилия","гемофилия C","фактор XI"]},{id:"blood-diseases-026",topicId:"blood-diseases",question:"Чем гемофилия C отличается от типов А и B по полу заболевших?",options:["Ею могут болеть и мужчины, и женщины в равной степени","Ею болеют только женщины","Ею болеют только новорождённые","Ею болеют только мужчины"],correctIndex:0,explanation:"В отличие от типов А и B, гемофилией C могут болеть и мужчины, и женщины в равной степени. Часто протекает в лёгкой форме.",difficulty:"hard",tags:["гемофилия","гемофилия C","пол"]},{id:"blood-diseases-027",topicId:"blood-diseases",question:"Как расшифровывается аббревиатура ОАК в диагностике болезней крови?",options:["Общий анализ крови (гемограмма)","Острый анализ крови","Объёмный анализ клеток","Общий анализ кроветворения"],correctIndex:0,explanation:"ОАК — общий анализ крови (гемограмма), включающий показатели WBC, RBC, PLT, HGB.",difficulty:"easy",tags:["диагностика","ОАК","гемограмма"]},{id:"blood-diseases-028",topicId:"blood-diseases",question:"Какой показатель общего анализа крови обозначается аббревиатурой WBC?",options:["Лейкоциты","Эритроциты","Тромбоциты","Гемоглобин"],correctIndex:0,explanation:"В гемограмме WBC — лейкоциты, RBC — эритроциты, PLT — тромбоциты, HGB — гемоглобин.",difficulty:"medium",tags:["диагностика","ОАК","WBC"]},{id:"blood-diseases-029",topicId:"blood-diseases",question:"Какой показатель общего анализа крови обозначается аббревиатурой RBC?",options:["Эритроциты","Лейкоциты","Тромбоциты","Гемоглобин"],correctIndex:0,explanation:"В гемограмме RBC — эритроциты, WBC — лейкоциты, PLT — тромбоциты, HGB — гемоглобин.",difficulty:"medium",tags:["диагностика","ОАК","RBC"]},{id:"blood-diseases-030",topicId:"blood-diseases",question:"Какой показатель общего анализа крови обозначается аббревиатурой PLT?",options:["Тромбоциты","Лейкоциты","Эритроциты","Гемоглобин"],correctIndex:0,explanation:"В гемограмме PLT — тромбоциты, HGB — гемоглобин, WBC — лейкоциты, RBC — эритроциты.",difficulty:"medium",tags:["диагностика","ОАК","PLT"]},{id:"blood-diseases-031",topicId:"blood-diseases",question:"Какой показатель общего анализа крови обозначается аббревиатурой HGB?",options:["Гемоглобин","Тромбоциты","Лейкоциты","Эритроциты"],correctIndex:0,explanation:"В гемограмме HGB — гемоглобин, PLT — тромбоциты, RBC — эритроциты, WBC — лейкоциты.",difficulty:"medium",tags:["диагностика","ОАК","HGB"]},{id:"blood-diseases-032",topicId:"blood-diseases",question:"Какие показатели входят в биохимический анализ крови при диагностике болезней крови?",options:["АЛТ, АСТ, билирубин, ферритин","WBC, RBC, PLT, HGB","Только уровень глюкозы","Только скорость оседания эритроцитов"],correctIndex:0,explanation:"Биохимический анализ крови включает АЛТ, АСТ, билирубин и ферритин.",difficulty:"hard",tags:["диагностика","биохимия","ферритин"]},{id:"blood-diseases-033",topicId:"blood-diseases",question:"Какой метод диагностики используется для прямого исследования кроветворения при болезнях крови?",options:["Биопсия и пункция костного мозга","Электрокардиография","Рентген грудной клетки","Спирометрия"],correctIndex:0,explanation:"Для диагностики болезней крови применяют биопсию и пункцию костного мозга, а также УЗИ печени и селезёнки.",difficulty:"medium",tags:["диагностика","костный мозг","биопсия"]},{id:"blood-diseases-034",topicId:"blood-diseases",question:"Какие органы исследуют с помощью УЗИ при диагностике болезней крови?",options:["Печень и селезёнку","Сердце и лёгкие","Почки и мочевой пузырь","Головной мозг"],correctIndex:0,explanation:"При диагностике болезней крови проводят УЗИ печени и селезёнки.",difficulty:"medium",tags:["диагностика","УЗИ","селезёнка"]},{id:"blood-diseases-035",topicId:"blood-diseases",question:"Какой антианемический препарат относится к группе фолиевой кислоты (по торговым названиям Folbiol, folinorm)?",options:["Фолиевая кислота","Цианокобаламин","Препарат железа","Аторвастатин"],correctIndex:0,explanation:"Фолиевая кислота выпускается под торговыми названиями Folbiol, folio, folinorm.",difficulty:"medium",tags:["лечение","антианемические","фолиевая кислота"]},{id:"blood-diseases-036",topicId:"blood-diseases",question:"Какие торговые названия имеют препараты железа (Fe)?",options:["Ferrum-lek, Ferrovin, Venofer","Folbiol, folinorm","Atoris, Vasolip","Aspirin kardio, Plavix"],correctIndex:0,explanation:"Препараты железа (Fe) выпускаются под названиями Ferrum-lek, Ferrovin, Venofer.",difficulty:"hard",tags:["лечение","антианемические","железо"]},{id:"blood-diseases-037",topicId:"blood-diseases",question:"Какой антианемический препарат соответствует витамину B12?",options:["Цианокобаламин","Фолиевая кислота","Препарат железа Venofer","Ферритин"],correctIndex:0,explanation:"Цианокобаламин — это витамин B12 (B12 vitamini), применяется в дозировках 200 и 500 мкг.",difficulty:"medium",tags:["лечение","антианемические","цианокобаламин","B12"]}];export{o as default};
